import {LANDSCAPE_FIELDS,LANDSCAPE_PRESETS,landscapeParams} from './landscape-engine.js';
export function validateLandscapeRecipe(r,assertSource){if(!r||r.version!==1||r.engine!=='landscape-sdr-v1'||!LANDSCAPE_PRESETS.some(p=>p.id===r.preset))throw Error('Invalid landscape recipe.');assertSource(r.source);if(r.skySource)assertSource(r.skySource);if(!Number.isInteger(r.width)||!Number.isInteger(r.height)||r.width<1||r.height<1||!Number.isSafeInteger(r.width*r.height*4))throw Error('Invalid landscape dimensions.');if(!r.params||Object.keys(r.params).length!==Object.keys(LANDSCAPE_FIELDS).length+1)throw Error('Incomplete landscape parameters.');landscapeParams(r.params);if(!Array.isArray(r.strokes)||r.strokes.length>80||r.strokes.reduce((n,s)=>n+(s.points?.length||0),0)>20000||r.strokes.some(s=>s.type!=='landscape-sky'||typeof s.add!=='boolean'||!Number.isFinite(s.radius)||s.radius<.001||s.radius>.3||!Array.isArray(s.points)||!s.points.length||s.points.some(p=>!Array.isArray(p)||p.length!==2||p.some(v=>!Number.isFinite(v)||v<0||v>1))))throw Error('Invalid landscape sky strokes.');return r;}
